const origin = scheme + parts[2].toLowerCase().replace(scheme === 'https://' ? /:443$/ : /:80$/, '');
const scope = $("Webhook (Crawl Trigger)").first().json.body.scope;
const wholeWebsite = scope === 'website' || scope === 'section';
return [{ json: {
  targetUrl: url,
