const sitemapUrls = [];
const lines = raw.split('\n');

const groups = [];
let currentGroup = null;

for (let line of lines) {
  line = line.replace(/#.*$/, '').trim();
  if (!line) continue;

  const colonIdx = line.indexOf(':');
  if (colonIdx === -1) continue;

  const directive = line.substring(0, colonIdx).trim().toLowerCase();
  const value = line.substring(colonIdx + 1).trim();

  if (directive === 'sitemap' &&
      (value.startsWith(config.origin + '/') || value.startsWith(config.origin.replace(/^http:/, 'https:') + '/'))) {
    sitemapUrls.push(value);
  }
  if (directive === 'user-agent') {
    const agent = value.toLowerCase();
    if (!currentGroup || currentGroup.hasRules) {
      currentGroup = { agents: [], rules: [], hasRules: false };
      groups.push(currentGroup);
    }
    currentGroup.agents.push(agent);
  } else if (currentGroup && (directive === 'disallow' || directive === 'allow')) {
    currentGroup.hasRules = true;
    if (!value) continue;

    const hasEndAnchor = value.endsWith('$');
    const cleanVal = hasEndAnchor ? value.slice(0, -1) : value;

    let regexStr = cleanVal
      .replace(/[.+?^${}()|[\]\\]/g, '\\$&')
      .replace(/\*/g, '.*');

    regexStr = '^' + regexStr + (hasEndAnchor ? '$' : '.*');

    currentGroup.rules.push({
      type: directive,
      path: value,
      pattern: regexStr,
      length: value.length
    });
  }
}

// 匹配优先级：优先专属 agent (crawl4ai)，若无则降级匹配通配符 *

const specific = groups.filter(group => group.agents.includes('crawl4ai'));
const rules = (specific.length ? specific : groups.filter(group => group.agents.includes('*')))
  .flatMap(group => group.rules);
const seedPath = config.targetUrl.match(/^https?:\/\/[^/?#]+(.*)$/i)?.[1] || '/';
const seedRules = rules.filter(rule => new RegExp(rule.pattern).test(seedPath.startsWith('?') ? '/' + seedPath : seedPath))
  .sort((a, b) => b.length - a.length || Number(b.type === 'allow') - Number(a.type === 'allow'));
return [{ json: {
  available, rules,
  seedAllowed: seedRules[0]?.type !== 'disallow',
  sitemapUrls: sitemapUrls.length ? [...new Set(sitemapUrls)] : [config.sitemapUrl],
  hasDeclaredSitemaps: sitemapUrls.length > 0
} }];

function websiteUrl(value, config, base = config.targetUrl) {
  if (typeof value !== 'string') return null;
  let url = value.trim().split('#')[0].replace(/&amp;/gi, '&');
  if (!url || /[\s\\]/.test(url)) return null;
  if (url.startsWith('//')) url = base.split(':')[0] + ':' + url;
  if (!/^[a-z][a-z0-9+.-]*:/i.test(url)) {
    const [, origin, path = '/'] = base.match(/^(https?:\/\/[^/?#]+)(\/[^?#]*)?/i) || [];
    if (!origin) return null;
    url = origin + (url.startsWith('/') ? url : url.startsWith('?') ? path + url :
      path.slice(0, path.lastIndexOf('/') + 1) + url);
  }
  const parts = url.match(/^(https?:\/\/[^/?#]+)(\/[^?#]*)?(\?[^#]*)?$/i);
  if (!parts) return null;
  const origin = parts[1].toLowerCase();
  const normalizedOrigin = origin.replace(origin.startsWith('https:') ? /:443$/ : /:80$/, '');
  if (normalizedOrigin !== config.origin && normalizedOrigin !== config.origin.replace(/^http:/, 'https:')) return null;
  const path = parts[2] || '/';
  const segments = [];
  for (const segment of path.split('/')) {
    const dot = segment.replace(/%2e/gi, '.');
    if (!dot || dot === '.') continue;
    if (dot === '..') { segments.pop(); continue; }
    if (/%2f|%5c/i.test(segment)) return null;
    segments.push(segment);
  }
  const pathname = '/' + segments.join('/');
  return normalizedOrigin + pathname + (pathname !== '/' && path.endsWith('/') ? '/' : '') + (parts[3] || '');
}
function pageKey(url) {
  const [path, query = ''] = url.split(/\?(.*)/s);
  const parameters = query.split('&').filter(Boolean).filter(value =>
    !/^(utm_.*|gad_.*|gclid|gbraid|wbraid|fbclid|msclkid)$/i.test(value.split('=')[0])).sort();
  return path.replace(/\/+$/, '') + (parameters.length ? '?' + parameters.join('&') : '');
}
function outputItems(name) {
  const node = $(name);
  if (!node.isExecuted) return [];
  const result = [];
  for (let run = 0; ; run++) {
    let items;
    try { items = node.all(0, run); } catch { break; }
    if (!items.length) break;
    result.push(...items);
  }
  return result;
}
const config = $("⚙️ Workflow Config (修改网站入口)").first().json;
const pages = [{url: config.targetUrl, lastmod: null}];
if (config.wholeWebsite) pages.push({url: config.origin + '/', lastmod: null});
const sitemaps = outputItems('Collect sitemap entries');
for (const sitemap of sitemaps) {
