const config = $("⚙️ Workflow Config (修改网站入口)").first().json;
const robots = $('Parse robots.txt Rules').first().json;
const previous = $runIndex > 0 ? $('Robots.txt & Gateway Filter').first(0, $runIndex - 1).json : null;
const seen = new Set(previous?.seen || []);
const incoming = $input.first().json;
const rules = robots.rules.map(rule => ({ ...rule, regex: new RegExp(rule.pattern) }))
  .sort((a, b) => b.length - a.length || Number(b.type === 'allow') - Number(a.type === 'allow'));
const urls = [];
let blockedByRobotsCount = previous?.diagnostics.blockedByRobotsCount || 0;
for (const page of incoming.pages || []) {
  const url = websiteUrl(page.url, config);
