    blockedByRobotsCount++;
    continue;
  }
  seen.add(key);
  urls.push({url, lastmod: page.lastmod || null});
}
const diagnostics = {
  sitemapCount: previous?.diagnostics.sitemapCount ?? incoming.sitemapCount ?? 0,
